import pandas as pd,numpy as np
from scipy.signal import lfilter, bilinear
from scipy.optimize import least_squares
fs={'vref1':'train/A_vref_op1.csv','amb1':'train/A_amb_op1.csv','vref3':'train/A_vref_op3.csv','amb2':'train/A_amb_op2.csv','gen':'train/A_gentrip_op1.csv','load2':'train/A_load_op2.csv','fault':'train/A_fault_op1.csv','line3':'train/A_line_op3.csv'}
D={}
dec=10
for k,f in fs.items():
    d=pd.read_csv(f).iloc[::dec]
    D[k]=dict(dt=dec*0.001,V=d.voltage_pu.values,th=d.bus_angle_rad.values,Vs=d.voltage_setpoint_pu.values,P=d.active_power_pu.values,Q=d.reactive_power_pu.values)
def tf(num,den,dt):
    b,a=bilinear(num,den,fs=1/dt); return b,a
def predQ(p,R):
    a1,a0,n1a,n0a,n1b,n0b=p
    dt=R['dt']
    ya=lfilter(*tf([n1a,n0a],[1,a1,a0],dt),R['Vs']-R['Vs'][0])
    yb=lfilter(*tf([n1b,n0b],[1,a1,a0],dt),R['V']-R['V'][0])
