    dt=R['dt']; th=R['th']-R['th'][0]
    lp=lfilter(*tf([1],[abs(Tw)+1e-3,1],dt),th)
    hp=th-lp
    yv=lfilter(*tf([1],[abs(a)+1e-3,1],dt),R['V']-R['V'][0])
    return kw*hp+kv*yv+R['P'][0]
kq=list(D.keys())
def resQ(p,keys): return np.concatenate([predQ(p,D[k])-D[k]['Q'] for k in keys])
def resP(p,keys): return np.concatenate([predP(p,D[k])-D[k]['P'] for k in keys])
