    try:
        r=least_squares(resQ,init,args=(kq,))
        print('Q',np.round(r.x,4),np.sqrt(np.mean(r.fun**2)))
        if best is None or r.cost<best.cost: best=r
    except Exception as e: print(e)
pq=best.x
for k in kq: print(k,np.sqrt(np.mean((predQ(pq,D[k])-D[k]['Q'])**2)))
rp=least_squares(resP,[0.5,-0.04,-0.05,0.1],args=(kq,))
print('P',np.round(rp.x,4),np.sqrt(np.mean(rp.fun**2)))
for k in kq: print(k,np.sqrt(np.mean((predP(rp.x,D[k])-D[k]['P'])**2)))
