import pandas as pd,numpy as np
from scipy.signal import lfilter, bilinear
from scipy.optimize import least_squares
fs={'vref1':'train/A_vref_op1.csv','amb1':'train/A_amb_op1.csv','vref3':'train/A_vref_op3.csv','amb2':'train/A_amb_op2.csv','gen':'train/A_gentrip_op1.csv','load2':'train/A_load_op2.csv','fault':'train/A_fault_op1.csv','line3':'train/A_line_op3.csv'}
D={}
dec=10
for k,f in fs.items():
    d=pd.read_csv(f).iloc[::dec]
    D[k]=dict(dt=dec*0.001,V=d.voltage_pu.values,th=d.bus_angle_rad.values,Vs=d.voltage_setpoint_pu.values,P=d.active_power_pu.values,Q=d.reactive_power_pu.values)
def tf(num,den,dt):
    return bilinear(num,den,fs=1/dt)
def predQ(p,R):
    c1,c0,a1,a0,d1,d0,b1,b0,kt,Tw=p
    dt=R['dt']
    ya=lfilter(*tf([c1,c0],[1,a1,a0],dt),R['Vs']-R['Vs'][0])
    yb=lfilter(*tf([d1,d0],[1,b1,b0],dt),R['V']-R['V'][0])
    th=R['th']-R['th'][0]
    hp=th-lfilter(*tf([1],[abs(Tw)+1e-3,1],dt),th)
    return ya+yb+kt*hp+R['Q'][0]
kq=list(D.keys())
def resQ(p,keys): return np.concatenate([predQ(p,D[k])-D[k]['Q'] for k in keys])
best=None
rng=np.random.default_rng(0)
for i in range(12):
    init=[rng.uniform(0.5,5),rng.uniform(-1,1),rng.uniform(2,30),rng.uniform(0.1,50),rng.uniform(-3,0),rng.uniform(-1,1),rng.uniform(2,30),rng.uniform(0.1,50),0.0,0.5]
    try:
        r=least_squares(resQ,init,args=(kq,),bounds=([-50,-50,0.01,0.001,-50,-50,0.01,0.001,-5,0.01],[50,50,200,2000,50,50,200,2000,5,10]))
        if best is None or r.cost<best.cost: best=r
    except Exception as e: pass
r=best
print(np.round(r.x,4),np.sqrt(np.mean(r.fun**2)))
for k in kq: print(k,np.sqrt(np.mean((predQ(r.x,D[k])-D[k]['Q'])**2)))
np.save('pq3.npy',r.x)
